function validateTechPt2(){const e=[];checkUpTechData.photo_irl||e.push("Фото салона (вод.дверь)");checkUpTechData.photo_irr||e.push("Фото салона (пер.прав дверь)");checkUpTechData.photo_engine||e.push("Фото моторного отсека");checkUpTechData.photo_trunk||e.push("Фото багажного отделения");return e}
addPhotoBlock(get("techPhoto_rl"),"Передний левый угол",e=>{checkUpTechData.photo_rl=e});addPhotoBlock(get("techPhoto_rr"),"Передний правый угол",e=>{checkUpTechData.photo_rr=e});addPhotoBlock(get("techPhoto_br"),"Задний правый угол",e=>{checkUpTechData.photo_br=e});addPhotoBlock(get("techPhoto_bl"),"Задний левый угол",e=>{checkUpTechData.photo_bl=e});addPhotoBlock(get("techPhoto_front"),"Спереди (бампер, капот, ветровое, крыша)",e=>{checkUpTechData.photo_front=e});addPhotoBlock(get("techPhoto_rear"),"Задняя часть (бампер, багажник, стекло, крыша)",e=>{checkUpTechData.photo_rear=e});addPhotoBlock(get("techPhoto_left"),"Левая сторона (бампера, крылья, двери)",e=>{checkUpTechData.photo_left=e});addPhotoBlock(get("techPhoto_right"),"Правая сторона (бампера, крылья, двери)",e=>{checkUpTechData.photo_right=e});addPhotoBlock(get("techPhoto_wfl"),"Общий вид переднего левого колеса",e=>{checkUpTechData.photo_wfl=e});addPhotoBlock(get("techPhoto_wfl_t"),"Протектор переднего левого колеса",e=>{checkUpTechData.photo_wfl_t=e});addPhotoBlock(get("techPhoto_wfr"),"Общий вид переднего правого колеса",e=>{checkUpTechData.photo_wfr=e});addPhotoBlock(get("techPhoto_wfr_t"),"Протектор переднего правого колеса",e=>{checkUpTechData.photo_wfr_t=e});addPhotoBlock(get("techPhoto_wrl"),"Общий вид заднего левого колеса",e=>{checkUpTechData.photo_wrl=e});addPhotoBlock(get("techPhoto_wrl_t"),"Протектор заднего левого колеса",e=>{checkUpTechData.photo_wrl_t=e});addPhotoBlock(get("techPhoto_wrr"),"Общий вид заднего правого колеса",e=>{checkUpTechData.photo_wrr=e});addPhotoBlock(get("techPhoto_wrr_t"),"Протектор заднего правого колеса",e=>{checkUpTechData.photo_wrr_t=e});addPhotoBlock(get("techPhoto_irl"),"Фото салона с открытой водительской дверью",e=>{checkUpTechData.photo_irl=e});addPhotoBlock(get("techPhoto_irr"),"Фото салона с открытой передней правой дверью",e=>{checkUpTechData.photo_irr=e});addPhotoBlock(get("techPhoto_ibr"),"Фото салона с открытой задней правой дверью (необязательно)",e=>{checkUpTechData.photo_ibr=e});addPhotoBlock(get("techPhoto_ibl"),"Фото салона с открытой задней левой дверью (необязательно)",e=>{checkUpTechData.photo_ibl=e});addPhotoBlock(get("techPhoto_engine"),"Фото моторного отсека",e=>{checkUpTechData.photo_engine=e});addPhotoBlock(get("techPhoto_trunk"),"Фото багажного отделения",e=>{checkUpTechData.photo_trunk=e});
get("offschedule_button")?.addEventListener("click",()=>{checkUpTechData.number=checkUpPostData.number;get("tech_pt1").classList.remove("hidden");get("tech_pt2").classList.add("hidden");nextPage("techcheck")});
get("techcheckBack")?.addEventListener("click",()=>{nextPage("car")});
get("tech_pt2back")?.addEventListener("click",()=>{get("tech_pt2").classList.add("hidden");get("tech_pt1").classList.remove("hidden");window.scrollTo(0,0)});
get("tech_topt2")?.addEventListener("click",()=>{const e=validateTechPt1();showStepError("techPt1Errors",e);e.length>0||(get("tech_pt1").classList.add("hidden"),get("tech_pt2").classList.remove("hidden"),window.scrollTo(0,0))});
get("tech_getLocation")?.addEventListener("click",()=>{const btn=get("tech_getLocation");btn.classList.add("inactive");btn.innerText="Получение координат...";navigator.geolocation.getCurrentPosition(p=>{checkUpTechData.geo=p.coords.latitude+" "+p.coords.longitude;get("tech_coords").innerText=p.coords.latitude+", "+p.coords.longitude;btn.classList.add("hidden")},()=>{btn.innerText="Не удалось получить координаты";btn.classList.remove("inactive")},{timeout:15e3,maximumAge:6e4})});
get("sendTechCheckup")?.addEventListener("click",async()=>{const errs=validateTechPt2();showStepError("techPt2Errors",errs);if(errs.length>0)return;checkUpTechData.wheels_ok=get("techWheelsOkSwitch")?.checked||false;const btn=get("sendTechCheckup"),orig="Завершить осмотр",payload=JSON.stringify({data:checkUpTechData,session:session});btn.classList.add("inactive");btn.innerText="Отправка...";try{const r=await postRequest(endpoint+"/api/tech-inspection",payload);if("ok"!==r?.status)return showSubmitError(formatSubmitFailure(null,r)),void(btn.innerText=orig);btn.innerText="Отчёт отправлен!";alert("Тех.осмотр успешно отправлен");setTimeout(()=>{location.reload()},1500)}catch(e){showSubmitError(formatSubmitFailure(e,null));btn.innerText=orig}finally{btn.classList.remove("inactive")}});
get("tech_report_button")?.addEventListener("click",()=>{window.open(endpoint+"/driver-app/tech-inspections","_blank")});